(function() {

    ['nova-xray', 'nova-toast'].forEach(id => {
        let el = document.getElementById(id);
        if(el) el.remove();
    });

    console.log("Axiom X-Ray Bot 10.0 (Automated Chaos Edition) Injected!");


    const style = document.createElement('style');
    style.textContent = `
        #nova-xray { position: fixed; top: 30px; left: 10px; z-index: 2147483647; display: flex; flex-direction: column; gap: 8px; background: rgba(0,0,0,0.6); padding: 8px; border-radius: 30px; cursor: move; user-select: none; touch-action: none; box-shadow: 0 4px 15px rgba(0,0,0,0.5); backdrop-filter: blur(5px); border: 1px solid #444; }
        .nx-btn { background: #000; color: #fff; border: 2px solid #333; border-radius: 50%; width: 40px; height: 40px; font-size: 18px; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: 0.3s; outline: none; }
        .nx-btn.active { background: #ea4335; border-color: #ea4335; box-shadow: 0 0 12px rgba(234,67,53,0.8); }

        #nova-toast { position: fixed; bottom: -60px; left: 50%; transform: translateX(-50%); background: #202124; color: #fff; padding: 12px 24px; border-radius: 30px; z-index: 2147483647; font-family: sans-serif; font-size: 14px; font-weight: bold; transition: bottom 0.4s cubic-bezier(0.18, 0.89, 0.32, 1.28); pointer-events: none; border: 1px solid #ff9800; box-shadow: 0 5px 15px rgba(0,0,0,0.5); white-space: nowrap; }
        #nova-toast.show { bottom: 50px; }


        @keyframes shakeX {
            0%, 100% { transform: translateX(0); }
            25% { transform: translateX(-12px) rotate(-5deg); }
            75% { transform: translateX(12px) rotate(5deg); }
        }
        @keyframes shakeY {
            0%, 100% { transform: translateY(0); }
            25% { transform: translateY(-12px); }
            75% { transform: translateY(12px); }
        }
        @keyframes crazySpin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
        @keyframes jellyPulse {
            0% { transform: scale(1); }
            50% { transform: scale(0.6) skewX(20deg); }
            100% { transform: scale(1.2) skewY(-20deg); }
        }


        .c-tilt { transform: rotate(90deg) !important; display: inline-block !important; transition: 0.3s !important; }
        .c-shake-x { animation: shakeX 0.3s infinite !important; display: inline-block !important; }
        .c-shake-y { animation: shakeY 0.4s infinite !important; display: inline-block !important; }
        .c-spin { animation: crazySpin 2s linear infinite !important; display: inline-block !important; }
        .c-jelly { animation: jellyPulse 0.8s infinite alternate !important; display: inline-block !important; }
    `;
    document.head.appendChild(style);


    const menu = document.createElement('div'); menu.id = 'nova-xray';
    const btnEdit = document.createElement('button'); btnEdit.className = 'nx-btn'; btnEdit.innerText = '✍️';
    const btnChaos = document.createElement('button'); btnChaos.className = 'nx-btn'; btnChaos.innerText = '👻';

    menu.appendChild(btnEdit); menu.appendChild(btnChaos);
    document.body.appendChild(menu);


    const toast = document.createElement('div'); toast.id = 'nova-toast'; document.body.appendChild(toast);
    let toastTimer;
    function reportToast(msg) {
        toast.innerText = msg; toast.classList.add('show');
        clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('show'), 2500);
    }


    let isDragging = false, startX, startY, initX, initY;
    function dragStart(e) {
        isDragging = false; let evt = e.type.includes('touch') ? e.touches[0] : e;
        startX = evt.clientX; startY = evt.clientY; let rect = menu.getBoundingClientRect();
        initX = rect.left; initY = rect.top;
        document.addEventListener(e.type.includes('touch') ? 'touchmove' : 'mousemove', dragMove, {passive: false});
        document.addEventListener(e.type.includes('touch') ? 'touchend' : 'mouseup', dragEnd);
    }
    function dragMove(e) {
        let evt = e.type.includes('touch') ? e.touches[0] : e;
        let dx = evt.clientX - startX; let dy = evt.clientY - startY;
        if (Math.abs(dx) > 5 || Math.abs(dy) > 5) {
            isDragging = true; e.preventDefault();
            menu.style.left = (initX + dx) + 'px'; menu.style.top = (initY + dy) + 'px';
            menu.style.right = 'auto'; menu.style.bottom = 'auto';
        }
    }
    function dragEnd() {
        document.removeEventListener('mousemove', dragMove); document.removeEventListener('mouseup', dragEnd);
        document.removeEventListener('touchmove', dragMove); document.removeEventListener('touchend', dragEnd);
    }
    menu.addEventListener('mousedown', dragStart); menu.addEventListener('touchstart', dragStart, {passive: false});

    // ✍️ Edit Mode
    btnEdit.onclick = () => {
        if (isDragging) return;
        let isEditOn = document.designMode === 'on';
        document.designMode = isEditOn ? 'off' : 'on';
        btnEdit.classList.toggle('active', !isEditOn);
        reportToast(!isEditOn ? "✍️ Edit Mode On!" : "✍️ Edit Mode Off!");
    };

    // 🔥 Auto Chaos Mode
    let isChaosOn = false;
    let consoleTrollInterval;
    let infectedElements = []; 


    const chaosClasses = ['c-tilt', 'c-shake-x', 'c-shake-y', 'c-spin', 'c-jelly'];

    btnChaos.onclick = () => {
        if (isDragging) return;
        isChaosOn = !isChaosOn;
        btnChaos.classList.toggle('active', isChaosOn);

        if (isChaosOn) {
            reportToast("🔥 Website is going CRAZY! \n Enjoy the dance!");

            document.querySelectorAll('button, a, input, img, select').forEach(el => {

                if (el.closest('#nova-xray') || el.closest('#nova-toast')) return;

                let randomChaos = chaosClasses[Math.floor(Math.random() * chaosClasses.length)];
                el.classList.add(randomChaos);
                infectedElements.push(el);
            });


            const trollMessages = [
                "❌ Error 404: Website CSS has committed suicide.",
                "⚠️ Warning: Buttons are on strike and refuse to be clicked.",
                "🛑 Critical Alert: The developer of this site is probably crying right now.",
                "💡 Tip: Try catching the buttons with a fishing net!"
            ];
            consoleTrollInterval = setInterval(() => {
                let msg = trollMessages[Math.floor(Math.random() * trollMessages.length)];
                console.log(`%c${msg}`, "color: #fff; font-size: 14px; font-weight: bold; background: #ea4335; padding: 5px 10px; border-radius: 5px;");
            }, 2000);

        } else {

            reportToast("🕊️ Chaos Mode Off. \n The website is resting now.");
            clearInterval(consoleTrollInterval);


            infectedElements.forEach(el => {
                chaosClasses.forEach(c => el.classList.remove(c));
            });
            infectedElements = []; 
        }
    };

})();
